{
  "impacts": [
    {
      "target": "CON-NOTICE-FORMAT",
      "obligation": "check_contract",
      "reason": "The accepted contract already permits SMS and requires desk opening hours. Re-check its application to every notification and both channel-specific length limits.",
      "source_evidence": [
        {
          "source_id": "toolshare:spec/requirements.md",
          "sha256": "ff5dae59d469eaa8e5ccd104ce6857802879e3b97104182b938c13f84f1fe755",
          "lines": [35, 36, 37, 38],
          "excerpt": "They are sent by email or, if the member prefers, by SMS. An SMS body is at most 160 characters; an email has a subject line and at most 500 characters of body text. Every message states the desk opening hours (Tue/Thu/Sat)."
        }
      ]
    },
    {
      "target": "REQ-READY-NOTICE",
      "obligation": "review_spec",
      "reason": "The ready-notice requirement specifies email, while the accepted format contract permits SMS according to member preference. Resolve the channel wording while preserving the tool and pickup-deadline content.",
      "source_evidence": [
        {
          "source_id": "toolshare:spec/requirements.md",
          "sha256": "ff5dae59d469eaa8e5ccd104ce6857802879e3b97104182b938c13f84f1fe755",
          "lines": [31, 32, 33, 35, 36],
          "excerpt": "When a held tool is ready to be picked up, we notify the member by email. ... The email names the tool and the pickup deadline. ... They are sent by email or, if the member prefers, by SMS."
        }
      ]
    },
    {
      "target": "toolshare:spec/architecture.md",
      "obligation": "review_spec",
      "reason": "The architecture describes the notification service as sending member emails, so its channel description needs review against the SMS-capable contract.",
      "source_evidence": [
        {
          "source_id": "toolshare:spec/architecture.md",
          "sha256": "1b7cc213e17478d47348158ee09173e4e423089739ce1c6c177527d6d2965300",
          "lines": [9, 10],
          "excerpt": "CMP-NOTIFY, the notification service (`toolshare/notifications.py`), sends member emails and implements REQ-READY-NOTICE. Every message it sends must follow CON-NOTICE-FORMAT."
        }
      ]
    },
    {
      "target": "CMP-NOTIFY",
      "obligation": "review_implementation",
      "reason": "The service implements only email and a 500-character limit; its ready message omits opening hours. Review channel selection, SMS limits and required content for all messages.",
      "source_evidence": [
        {
          "source_id": "git:toolshare@3e93b8e1693e95c68fd953f7bf71da76cd8717aa:toolshare/notifications.py",
          "sha256": "ae80be0576750da1fc879a76854887e3233dfbcab1c6b301b84ae84d16dd33b7",
          "lines": [1, 4, 7, 8, 9, 10, 13, 14],
          "excerpt": "Member notifications (plain-text email). ... MAX_BODY = 500 ... def send_email(member: str, subject: str, body: str) ... def send_ready_notice(member: str, tool: str, deadline: str) ... Your hold on {tool} is ready. Collect it by {deadline}."
        }
      ]
    },
    {
      "target": "CMP-HOLDS",
      "obligation": "review_implementation",
      "reason": "Hold expiry directly sends an email whose body omits opening hours; this notification path must also comply with the changed format and applicable channel preference.",
      "source_evidence": [
        {
          "source_id": "git:toolshare@3e93b8e1693e95c68fd953f7bf71da76cd8717aa:toolshare/holds.py",
          "sha256": "b3024276c517744afea68dfec8b1041dc3e488d6125307cb1a36f40819fe1ecf",
          "lines": [6, 23, 24, 25, 26, 27, 28, 29],
          "excerpt": "from toolshare.notifications import send_email ... send_email(lapsed, f\"Your hold on {tool} has lapsed\", ... \"member in the queue. You can place a new hold at any time.\")"
        }
      ]
    },
    {
      "target": "TEST-NOTICE-FORMAT",
      "obligation": "rerun_test",
      "reason": "Extend and rerun the format tests for SMS selection and the 160-character boundary, opening hours on every message, and retained email and ready-notice requirements.",
      "source_evidence": [
        {
          "source_id": "git:toolshare@3e93b8e1693e95c68fd953f7bf71da76cd8717aa:tests/test_notifications.py",
          "sha256": "5723cb01fb2199145f4388ba8e9c0359c7c874acef4cd626516428337b5cd1e4",
          "lines": [6, 7, 8, 9, 12, 13, 14],
          "excerpt": "assert msg[\"subject\"] and len(msg[\"body\"]) <= 500 ... notifications.send_email(\"ana\", \"s\", \"x\" * 501)"
        },
        {
          "source_id": "toolshare:spec/architecture.md",
          "sha256": "1b7cc213e17478d47348158ee09173e4e423089739ce1c6c177527d6d2965300",
          "lines": [11, 12],
          "excerpt": "TEST-NOTICE-FORMAT (`tests/test_notifications.py`) checks messages against CON-NOTICE-FORMAT."
        }
      ]
    },
    {
      "target": "TEST-HOLD-QUEUE",
      "obligation": "rerun_test",
      "reason": "The expiry test invokes the holds notification path and checks its recipient; rerun it after changing that path and cover format compliance for the lapse message.",
      "source_evidence": [
        {
          "source_id": "git:toolshare@3e93b8e1693e95c68fd953f7bf71da76cd8717aa:tests/test_holds.py",
          "sha256": "1d75cbe25e962f50d6f2b7d6dc3f1bfbc0535f1fa588658d75a13e6bdd0a413b",
          "lines": [4, 8, 9, 10],
          "excerpt": "def test_queue_order_and_expiry(): ... assert holds.expire_hold(\"drill\") == \"ben\" ... assert notifications.OUTBOX[-1][\"to\"] == \"ana\""
        }
      ]
    }
  ],
  "unresolved_questions": [
    "Does SMS replace the email requirement for ready notices when a member prefers SMS, or must ready notices still always be emailed?",
    "Where are member channel preferences and SMS destinations obtained, and what happens when they are unavailable?",
    "Are Tue/Thu/Sat sufficient as opening-hours content, or must messages include specific opening and closing times?",
    "How should messages handle tool names or deadlines that make required content exceed the applicable body limit?"
  ]
}
